import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLength = scanner.nextInt();
        String inputString = scanner.next();
        int maxSegmentLength = -1, currentSegmentLength = 0;
        for (int index = 0; index < totalLength; index++) {
            char ch = inputString.charAt(index);
            if (ch == '_') {
                if (currentSegmentLength > maxSegmentLength) maxSegmentLength = currentSegmentLength;
                currentSegmentLength = 0;
            } else if (ch != '(' && ch != ')') {
                currentSegmentLength++;
            } else {
                if (currentSegmentLength > maxSegmentLength) maxSegmentLength = currentSegmentLength;
                currentSegmentLength = 0;
                index++;
                while (index < totalLength && inputString.charAt(index) != ')') index++;
            }
        }
        if (currentSegmentLength > maxSegmentLength) maxSegmentLength = currentSegmentLength;

        int totalWords = 0, currentWordSize = 0;
        for (int index = 0; index < totalLength; index++) {
            if (inputString.charAt(index) == '(') {
                index++;
                while (index < totalLength && inputString.charAt(index) != ')') {
                    if (inputString.charAt(index) == '_') {
                        if (currentWordSize > 0) totalWords++;
                        currentWordSize = 0;
                    } else if (inputString.charAt(index) != '_') {
                        currentWordSize++;
                    }
                    index++;
                }
                if (currentWordSize > 0) totalWords++;
                currentWordSize = 0;
            }
        }
        System.out.println(maxSegmentLength + " " + totalWords);
    }
}
